-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.model_governance_metrics
COMMENT 'Governance KPIs over the model estate - how many models and versions exist, how many are champion versus challenger or retired, by type and purpose. The AI-governance readout the semantic layer can answer directly: which models decide, and are they under control. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_model.model_version

joins:
  - name: model_asset
    source: lr_serverless_aws_us_catalog.bricksurance_model.model_asset
    on: source.model_id = model_asset.model_id

dimensions:
  - name: model_purpose_code
    expr: model_asset.model_purpose_code
  - name: model_type_code
    expr: model_asset.model_type_code
  - name: model_status_code
    expr: source.model_status_code
  - name: line_of_business_code
    expr: model_asset.line_of_business_code

measures:
  - name: model_version_count
    expr: COUNT(DISTINCT model_version_id)
  - name: model_count
    expr: COUNT(DISTINCT source.model_id)
  - name: champion_count
    expr: COUNT(DISTINCT CASE WHEN model_status_code = 'CHAMPION' THEN model_version_id END)
  - name: challenger_count
    expr: COUNT(DISTINCT CASE WHEN model_status_code = 'CHALLENGER' THEN model_version_id END)
  - name: retired_count
    expr: COUNT(DISTINCT CASE WHEN model_status_code = 'RETIRED' THEN model_version_id END)
$$;
